it('should initialize database and run migrations', async () => {
  await initDb();
  const result = await db.query("SELECT name FROM sqlite_master WHERE type='table' AND name='todos'");
  expect(result).toHaveLength(1);
  const columns = await db.query('PRAGMA table_info(todos)');
  expect(columns.map(c => c.name)).toContain('deleted');
});

it('should not reinitialize database if already initialized', async () => {
  await initDb();
  const firstDb = db;
  await initDb();
  expect(db).toBe(firstDb);
});

it('should add a todo with valid text', async () => {
  await initDb();
  await addTodo('Buy groceries');
  const todos = await getTodos();
  expect(todos).toHaveLength(1);
  expect(todos[0].text).toBe('Buy groceries');
  expect(todos[0].completed).toBe(0);
});

it('should handle empty string input', async () => {
  await initDb();
  await addTodo('');
  const todos = await getTodos();
  expect(todos[0].text).toBe('');
});

it('should log error when database insert fails', async () => {
  const consoleError = jest.spyOn(console, 'error').mockImplementation();
  db = { execute: jest.fn().mockRejectedValue(new Error('DB error')) };
  await addTodo('test');
  expect(consoleError).toHaveBeenCalledWith('Failed to add todo:', expect.any(Error));
  consoleError.mockRestore();
});

it('should return only non-deleted todos in descending order', async () => {
  await initDb();
  await addTodo('First');
  await addTodo('Second');
  await addTodo('Third');
  const todos = await getTodos();
  expect(todos).toHaveLength(3);
  expect(todos[0].text).toBe('Third');
  expect(todos[2].text).toBe('First');
});

it('should exclude deleted todos from results', async () => {
  await initDb();
  await addTodo('Keep this');
  await addTodo('Delete this');
  const all = await getTodos();
  await deleteTodo(all[0].id);
  const remaining = await getTodos();
  expect(remaining).toHaveLength(1);
  expect(remaining[0].text).toBe('Keep this');
});

it('should return empty array when no todos exist', async () => {
  await initDb();
  const todos = await getTodos();
  expect(todos).toEqual([]);
});

it('should toggle todo completed status from false to true', async () => {
  await initDb();
  await addTodo('Toggle me');
  const todos = await getTodos();
  await toggleTodo(todos[0].id);
  const updated = await getTodos();
  expect(updated[0].completed).toBe(1);
});

it('should toggle completed todo back to incomplete', async () => {
  await initDb();
  await addTodo('Toggle twice');
  const todos = await getTodos();
  await toggleTodo(todos[0].id);
  await toggleTodo(todos[0].id);
  const final = await getTodos();
  expect(final[0].completed).toBe(0);
});

it('should silently succeed when toggling non-existent id', async () => {
  await initDb();
  await expect(toggleTodo(99999)).resolves.not.toThrow();
});

it('should update todo text successfully', async () => {
  await initDb();
  await addTodo('Original text');
  const todos = await getTodos();
  await updateTodo(todos[0].id, 'Updated text');
  const updated = await getTodos();
  expect(updated[0].text).toBe('Updated text');
});

it('should throw error when update fails', async () => {
  await initDb();
  db = { execute: jest.fn().mockRejectedValue(new Error('Update failed')) };
  await expect(updateTodo(1, 'test')).rejects.toThrow('Update failed');
});

it('should not throw when updating non-existent id', async () => {
  await initDb();
  await expect(updateTodo(99999, 'ghost')).resolves.not.toThrow();
});

it('should soft delete todo by setting deleted flag', async () => {
  await initDb();
  await addTodo('Delete me');
  const todos = await getTodos();
  await deleteTodo(todos[0].id);
  const remaining = await getTodos();
  expect(remaining).toHaveLength(0);
  const all = await db.query('SELECT * FROM todos');
  expect(all).toHaveLength(1);
  expect(all[0].deleted).toBe(1);
});

it('should throw error when delete fails', async () => {
  await initDb();
  db = { execute: jest.fn().mockRejectedValue(new Error('Delete failed')) };
  await expect(deleteTodo(1)).rejects.toThrow('Delete failed');
});

it('should not throw when deleting non-existent id', async () => {
  await initDb();
  await expect(deleteTodo(99999)).resolves.not.toThrow();
});

it('should handle concurrent operations safely', async () => {
  await initDb();
  await addTodo('Concurrent test');
  const todos = await getTodos();
  await Promise.all([toggleTodo(todos[0].id), updateTodo(todos[0].id, 'Updated'), toggleTodo(todos[0].id)]);
  const final = await getTodos();
  expect(final[0].text).toBe('Updated');
});

